/** Fulfillment hubs (see footer: Dhaka Central DAC1, Chittagong Port CTG2). */
export const HUBS: { id: string; code: string; name: string }[] = [
  { id: "dhaka", code: "DAC1", name: "Dhaka Central Hub" },
  { id: "chattogram", code: "CTG2", name: "Chattogram Port Hub" },
];

const district = (name: string) => {
  const point = DISTRICT_POINTS.find((d) => d.name === name);
  if (!point) throw new Error(`Unknown district point: ${name}`);
  return point;
};

export interface Route {
  from: MapPoint;
  to: MapPoint;
  /** Trunk routes are hub linehauls (brighter, with a moving parcel); the rest are last-mile. */
  trunk: boolean;
}

const C = DIVISION_CITIES;

export const ROUTES: Route[] = [
  // DAC1 linehauls to every divisional headquarters
  ...["mymensingh", "sylhet", "rajshahi", "rangpur", "khulna", "barishal", "chattogram"].map((id) => ({
    from: C.dhaka,
    to: C[id],
    trunk: true,
  })),
  // CTG2 serves the south-east
  ...["Cox's Bazar", "Rangamati", "Cumilla", "Noakhali"].map((name) => ({
    from: C.chattogram,
    to: district(name),
    trunk: true,
  })),
  // Last-mile from divisional cities to districts
  { from: C.dhaka, to: district("Tangail"), trunk: false },
  { from: C.dhaka, to: district("Faridpur"), trunk: false },
  { from: C.rajshahi, to: district("Bogura"), trunk: false },
  { from: C.rajshahi, to: district("Pabna"), trunk: false },
  { from: C.rangpur, to: district("Dinajpur"), trunk: false },
  { from: C.rangpur, to: district("Thakurgaon"), trunk: false },
  { from: C.khulna, to: district("Jashore"), trunk: false },
  { from: C.khulna, to: district("Satkhira"), trunk: false },
  { from: C.khulna, to: district("Kushtia"), trunk: false },
  { from: C.barishal, to: district("Patuakhali"), trunk: false },
  { from: C.sylhet, to: district("Sunamganj"), trunk: false },
  { from: C.chattogram, to: district("Bandarban"), trunk: false },
];

